css:
#famScreen,#famScreen :where(*:not(svg,svg *)),#famScreen :where(*:not(svg,svg *))::before,#famScreen :where(*:not(svg,svg *))::after{all:revert}
@keyframes fp_heropulse { 
  0% { box-shadow: rgba(46, 125, 91, 0.5) 0px 0px 0px 0px; }
  70% { box-shadow: rgba(46, 125, 91, 0) 0px 0px 0px 10px; }
  100% { box-shadow: rgba(46, 125, 91, 0) 0px 0px 0px 0px; }
}
#famScreen .leaflet-pane,#famScreen .leaflet-tile,#famScreen .leaflet-marker-icon,#famScreen .leaflet-marker-shadow,#famScreen .leaflet-tile-container,#famScreen .leaflet-pane > svg,#famScreen .leaflet-pane > canvas,#famScreen .leaflet-zoom-box,#famScreen .leaflet-image-layer,#famScreen .leaflet-layer{position: absolute; left: 0px; top: 0px;}
#famScreen .leaflet-tile,#famScreen .leaflet-marker-icon,#famScreen .leaflet-marker-shadow{user-select: none; -webkit-user-drag: none;}
#famScreen .leaflet-tile::selection{background: transparent;}
#famScreen .leaflet-container .leaflet-overlay-pane svg{max-width: none !important; max-height: none !important;}
#famScreen .leaflet-container .leaflet-marker-pane img,#famScreen .leaflet-container .leaflet-shadow-pane img,#famScreen .leaflet-container .leaflet-tile-pane img,#famScreen .leaflet-container img.leaflet-image-layer,#famScreen .leaflet-container .leaflet-tile{width: auto; padding: 0px; max-width: none !important; max-height: none !important;}
#famScreen .leaflet-container img.leaflet-tile{mix-blend-mode: plus-lighter;}
#famScreen .leaflet-container.leaflet-touch-zoom{touch-action: pan-x pan-y;}
#famScreen .leaflet-tile{filter: inherit; visibility: hidden;}
#famScreen .leaflet-tile-loaded{visibility: inherit;}
#famScreen .leaflet-overlay-pane svg{}
#famScreen .leaflet-pane{z-index: 400;}
#famScreen .leaflet-tile-pane{z-index: 200;}
#famScreen .leaflet-overlay-pane{z-index: 400;}
#famScreen .leaflet-shadow-pane{z-index: 500;}
#famScreen .leaflet-marker-pane{z-index: 600;}
#famScreen .leaflet-tooltip-pane{z-index: 650;}
#famScreen .leaflet-popup-pane{z-index: 700;}
#famScreen .leaflet-map-pane svg{z-index: 200;}
#famScreen .leaflet-top,#famScreen .leaflet-bottom{position: absolute; z-index: 1000; pointer-events: none;}
#famScreen .leaflet-top{top: 0px;}
#famScreen .leaflet-right{right: 0px;}
#famScreen .leaflet-bottom{bottom: 0px;}
#famScreen .leaflet-left{left: 0px;}
#famScreen .leaflet-zoom-animated{transform-origin: 0px 0px;}
#famScreen svg.leaflet-zoom-animated{will-change: transform;}
#famScreen .leaflet-interactive{cursor: pointer;}
#famScreen .leaflet-popup-pane,#famScreen .leaflet-control{cursor: auto;}
#famScreen .leaflet-marker-icon,#famScreen .leaflet-marker-shadow,#famScreen .leaflet-image-layer,#famScreen .leaflet-pane > svg path,#famScreen .leaflet-tile-container{pointer-events: none;}
#famScreen .leaflet-marker-icon.leaflet-interactive,#famScreen .leaflet-image-layer.leaflet-interactive,#famScreen .leaflet-pane > svg path.leaflet-interactive,#famScreen svg.leaflet-image-layer.leaflet-interactive path{pointer-events: auto;}
#famScreen .leaflet-marker-icon,#famScreen .leaflet-marker-shadow{display: block;}
#famScreen .leaflet-container.leaflet-touch-drag{touch-action: pinch-zoom;}
#famScreen .leaflet-container.leaflet-touch-drag.leaflet-touch-zoom{touch-action: none;}
#famScreen .leaflet-container a{color: rgb(0, 120, 168);}
#famScreen .leaflet-control{float: left; clear: both;}
#famScreen .leaflet-right .leaflet-control{margin-right: 10px;}
#famScreen .leaflet-top .leaflet-control{margin-top: 10px;}
#famScreen .leaflet-bottom .leaflet-control{margin-bottom: 10px;}
#famScreen .leaflet-left .leaflet-control{margin-left: 10px;}
#famScreen .leaflet-grab{cursor: grab;}
#famScreen .leaflet-bar{box-shadow: rgba(0, 0, 0, 0.65) 0px 1px 5px; border-radius: 4px;}
#famScreen .leaflet-bar a{background-color: rgb(255, 255, 255); border-bottom: 1px solid rgb(204, 204, 204); width: 26px; height: 26px; line-height: 26px; display: block; text-align: center; text-decoration: none; color: black;}
#famScreen .leaflet-bar a,#famScreen .leaflet-control-layers-toggle{background-position: 50% 50%; background-repeat: no-repeat; display: block;}
#famScreen .leaflet-bar a:first-child{border-top-left-radius: 4px; border-top-right-radius: 4px;}
#famScreen .leaflet-bar a:last-child{border-bottom-left-radius: 4px; border-bottom-right-radius: 4px; border-bottom: none;}
#famScreen .leaflet-touch .leaflet-bar a{width: 30px; height: 30px; line-height: 30px;}
#famScreen .leaflet-touch .leaflet-bar a:first-child{border-top-left-radius: 2px; border-top-right-radius: 2px;}
#famScreen .leaflet-touch .leaflet-bar a:last-child{border-bottom-left-radius: 2px; border-bottom-right-radius: 2px;}
#famScreen .leaflet-control-zoom-in,#famScreen .leaflet-control-zoom-out{font: bold 18px "Lucida Console", Monaco, monospace; text-indent: 1px;}
#famScreen .leaflet-touch .leaflet-control-zoom-in,#famScreen .leaflet-touch .leaflet-control-zoom-out{font-size: 22px;}
#famScreen .leaflet-container .leaflet-control-attribution{background: rgba(255, 255, 255, 0.8); margin: 0px;}
#famScreen .leaflet-control-attribution,#famScreen .leaflet-control-scale-line{padding: 0px 5px; color: rgb(51, 51, 51); line-height: 1.4;}
#famScreen .leaflet-control-attribution a{text-decoration: none;}
#famScreen .leaflet-attribution-flag{width: 1em; height: 0.6669em; display: inline !important; vertical-align: baseline !important;}
#famScreen .leaflet-touch .leaflet-control-attribution,#famScreen .leaflet-touch .leaflet-control-layers,#famScreen .leaflet-touch .leaflet-bar{box-shadow: none;}
#famScreen .leaflet-touch .leaflet-control-layers,#famScreen .leaflet-touch .leaflet-bar{border: 2px solid rgba(0, 0, 0, 0.2); background-clip: padding-box;}
#famScreen #hp_leaflet-map{height: 260px !important;}
#famScreen *,#famScreen ::before,#famScreen ::after{box-sizing: border-box; min-width: 0px;}
#famScreen img,#famScreen picture,#famScreen video,#famScreen canvas,#famScreen svg{max-width: 100%; height: auto; display: block;}
#famScreen input,#famScreen select,#famScreen textarea,#famScreen button{font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-size: max(16px, 1em); max-width: 100%;}
#famScreen textarea::placeholder,#famScreen input::placeholder{color: rgba(184, 207, 212, 0.4);}
#famScreen .card-row-value,#famScreen .visit-detail-val,#famScreen .visit-hours,#famScreen .msg-bubble-time{font-family: var(--mono); font-variant-numeric: tabular-nums;}
#famScreen ::-webkit-scrollbar{width: 3px;}
#famScreen ::-webkit-scrollbar-track{background: transparent;}
#famScreen ::-webkit-scrollbar-thumb{background: rgba(0, 0, 0, 0.1); border-radius: 3px;}
#famScreen .pin-btn,#famScreen .msg-send-btn,#famScreen .sched-submit,#famScreen .sched-cancel,#famScreen .star-btn,#famScreen .lb-close,#famScreen .map-sheet-close,#famScreen .tb-signout,#famScreen .visit-row,#famScreen .psw-card,#famScreen .sched-opt,#famScreen .photo-cell,#famScreen .photo-group-head,#famScreen .care-pause-banner,#famScreen .nav-btn{transition: transform .12s var(--e), background .12s var(--e); -webkit-tap-highlight-color: transparent;}
#famScreen .section-title + .card,#famScreen .section-title + div > .card{margin-top: 0px !important;}
#famScreen{color-scheme:dark}
#famScreen *,#famScreen,#famScreen{box-sizing: border-box; min-width: 0px;}
#famScreen{overflow: clip auto; overscroll-behavior-y: contain; text-size-adjust: 100%; max-width: 100%;}
#famScreen,#famScreen .pd-body{overflow-x: clip;}
#famScreen .pd-body{overflow-x: clip; min-height: 762px; margin: 0px; padding-bottom: calc(80px + env(safe-area-inset-bottom)); -webkit-tap-highlight-color: transparent; overflow-wrap: anywhere; word-break: break-word;}
#famScreen img,#famScreen svg{max-width: 100%; height: auto; display: block;}
#famScreen textarea,#famScreen button{font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-size: max(16px, 1em); max-width: 100%;}
#famScreen .leaflet-container{max-width: 100%; width: 100% !important; height: 100% !important;}
#famScreen,#famScreen .pd-body{min-height: 762px; font-family: var(--sans),sans-serif; background: var(--bg); color: var(--text); -webkit-font-smoothing: antialiased;}
#famScreen .gate-brand{font-family: Inter, sans-serif; font-size: 26px; font-weight: 650; letter-spacing: -0.3px; color: var(--text); text-align: center; margin-bottom: 5px;}
#famScreen .gate-sub{text-align: center; font-size: 11px; letter-spacing: 2.5px; text-transform: uppercase; color: var(--muted); margin-bottom: 36px;}
#famScreen .pin-btn:hover{background: var(--green-l); border-color: var(--accent);}
#famScreen .pin-btn.del{font-size: 16px; color: var(--muted);}
@keyframes pin-shake { 
  0%, 100% { transform: translateX(0px); }
  20% { transform: translateX(-6px); }
  40% { transform: translateX(6px); }
  60% { transform: translateX(-4px); }
  80% { transform: translateX(4px); }
}
#famScreen .tb-brand{font-family: var(--mono); font-size: 10px; letter-spacing: 1.5px; text-transform: uppercase; color: var(--teal2); flex: 1 1 0%; min-width: 0px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;}
#famScreen .tb-right{display: flex; align-items: center; gap: 8px; flex-shrink: 0;}
#famScreen .tb-name{font-size: 13px; color: var(--muted); font-weight: 500; max-width: 90px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;}
#famScreen .status-card{background: rgba(30, 122, 72, 0.18); border: 1px solid rgba(46, 125, 91, 0.35); border-radius: 20px; padding: 24px; margin-bottom: 20px; position: relative; overflow: hidden;}
#famScreen .status-card.status-active{background: rgba(30, 122, 72, 0.22); border-color: rgba(46, 160, 100, 0.4);}
@keyframes pulse-dot { 
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}
#famScreen .msg-input-field::placeholder{color: rgba(184, 207, 212, 0.4);}
#famScreen textarea::placeholder{color: rgba(184, 207, 212, 0.4);}
@keyframes spin { 
  100% { transform: rotate(360deg); }
}
@keyframes map-pulse { 
  0%, 100% { box-shadow: rgba(74, 154, 110, 0.4) 0px 0px 0px 3px, rgba(74, 154, 110, 0.6) 0px 0px 12px; }
  50% { box-shadow: rgba(74, 154, 110, 0.15) 0px 0px 0px 6px, rgba(74, 154, 110, 0.4) 0px 0px 16px; }
}
@keyframes fadeInDown { 
  0% { opacity: 0; transform: translateX(-50%) translateY(-12px); }
  100% { opacity: 1; transform: translateX(-50%) translateY(0px); }
}
@keyframes fam-shimmer { 
  0% { background-position: 200% 0px; }
  100% { background-position: -200% 0px; }
}
#famScreen button{transition: transform 50ms; touch-action: manipulation; -webkit-tap-highlight-color: transparent;}
#famScreen button:active{transform: scale(0.98);}
#famScreen .eta-banner{margin: 12px 16px 0px; padding: 12px 14px; background: rgba(52, 211, 153, 0.06); border: 1px solid rgba(52, 211, 153, 0.2); border-radius: 10px; display: flex; align-items: center; gap: 10px;}
#famScreen .eta-dot{width: 8px; height: 8px; border-radius: 50%; background: var(--teal2); animation: 1.5s ease 0s infinite normal none running livepulse; flex-shrink: 0;}
@keyframes livepulse { 
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}
#famScreen .eta-text{font-size: 15px; color: var(--text);}
#famScreen .eta-time{font-family: var(--mono); font-size: 11px; color: var(--teal2); margin-top: 2px;}
#famScreen .client-alert-chip{display: inline-flex; align-items: center; gap: 4px; font-family: var(--mono); font-size: 11px; letter-spacing: 1px; text-transform: uppercase; padding: 3px 8px; border-radius: 100px; border: 1px solid; margin-right: 4px;}
#famScreen .client-alert-chip.fall{color: var(--amber); border-color: rgba(224, 154, 61, 0.3);}
#famScreen .client-alert-chip.allergy{color: var(--red); border-color: rgba(224, 85, 85, 0.3);}
#famScreen .client-alert-chip.env{color: rgb(109, 189, 212); border-color: rgba(255, 255, 255, 0.3);}
#famScreen .section-title{font-family: var(--mono); font-size: 12px; letter-spacing: 1.5px; text-transform: uppercase; color: var(--muted); margin-bottom: 10px;}
#famScreen{--rb-void: #06080c; --rb-base: #0a0e14; --rb-panel: #0e131b; --rb-line: rgba(255,255,255,.07); --rb-line2: rgba(255,255,255,.13); --rb-text: #eef2f6; --rb-dim: #a6b3bf; --rb-faint: rgba(238,242,246,.62); --rb-primary: #34D399; --rb-primary-bright: #5ce0a8; --rb-gold: #f0b549; --rb-serif: 'Fraunces',serif; --rb-sans: 'Space Grotesk',sans-serif; --rb-mono: 'DM Mono',monospace; --sys-gps: #38bdf8; --sys-invoice: #fbbf24; --sys-family: #34d399; --sys-sched: #a78bfa; --sys-ai: #2dd4bf; --sys-lead: #fb7185; --e: cubic-bezier(.22,1,.36,1); --e-snap: cubic-bezier(.34,1.56,.64,1); --t1: 120ms; --t2: 200ms; --t3: 340ms; --t4: 560ms; --c-bg: #F7F8F5; --c-surface: #FFFFFF; --c-ink: #1B2A24; --c-ink-muted: #4B5A52; --c-good: #2E7D5B; --c-good-soft: #E4F1EA; --c-warn: #B26A00; --c-emergency: #B3261E; --fs-base: 18px; --fs-lg: 22px; --fs-xl: 28px; --lh-body: 1.6; --bg: var(--rb-void); --bg2: var(--rb-panel); --bg3: #151A21; --surface: var(--rb-panel); --border: var(--rb-line); --border2: var(--rb-line2); --text: var(--rb-text); --muted: var(--rb-dim); --muted2: var(--rb-dim); --accent: var(--rb-primary); --teal: var(--rb-primary); --teal2: var(--rb-primary); --teal3: var(--rb-primary); --gold: var(--rb-gold); --red: #e05555; --amber: #e09a3d; --green2: #4a9a6e; --mono: 'DM Mono',monospace; --sans: var(--rb-sans); --serif: var(--rb-serif); --safe-bottom: env(safe-area-inset-bottom); --success: #4a9a6e; --warning: #e09a3d; --error: #e05555; --green: #4a9a6e; --green-l: rgba(74,154,110,.1); --green-b: rgba(74,154,110,.2); --green-d: #2a6a4a; --shadow: rgba(0,0,0,.3);}
#famScreen .gate{position: fixed; inset: 0px; background: var(--surface); z-index: 100; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 20px;}
#famScreen .gate.hide{display: none;}
#famScreen .gate-inner{width: 100%; max-width: min(380px, -40px + 390px); margin: 0px auto;}
#famScreen .gate-brand{font-family: Inter, sans-serif; font-size: 22px; font-weight: 600; color: var(--text); text-align: center; margin-bottom: 4px;}
#famScreen .gate-brand em{color: var(--green); font-style: normal;}
#famScreen .gate-sub{text-align: center; font-size: 14px; color: var(--muted); margin-bottom: 40px;}
#famScreen .gate-card{background: var(--bg2); border-radius: 22px; padding: 34px 26px 26px; border: 1px solid var(--border);}
#famScreen .gate-hint{font-size: 14px; color: var(--muted); text-align: center; margin-bottom: 28px; line-height: 1.6;}
#famScreen .pin-dots{display: flex; gap: 16px; justify-content: center; margin-bottom: 30px;}
#famScreen .pin-dot{width: 12px; height: 12px; border-radius: 50%; border: 1.5px solid var(--border2); transition: 0.18s;}
#famScreen .pin-pad{display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; justify-items: center;}
#famScreen .pin-btn{width: 72px; height: 72px; margin: 0px auto; padding: 0px; border-radius: 50%; border: 1px solid var(--border2); background: rgba(255, 255, 255, 0.024); font-size: 24px; font-weight: 400; font-family: Inter, sans-serif; color: var(--text); cursor: pointer; display: flex; align-items: center; justify-content: center; transition: background 0.12s, border-color 0.12s, transform 0.12s; touch-action: manipulation; -webkit-tap-highlight-color: transparent; user-select: none;}
#famScreen .pin-btn:active{background: rgba(255, 255, 255, 0.07); border-color: var(--accent); transform: scale(0.94);}
#famScreen .pin-btn.del{color: var(--muted);}
#famScreen .pin-btn.del svg{width: 22px; height: 22px; display: block; margin: 0px auto;}
#famScreen .pin-btn.empty{background: none; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; cursor: default; pointer-events: none;}
#famScreen .pin-error{text-align: center; font-size: 13px; color: var(--error); margin-top: 14px; opacity: 0; transition: opacity 0.2s; min-height: 20px;}
#famScreen .app{display: none; flex-direction: column; min-height: 762px;}
#famScreen .app.show{display: flex;}
#famScreen .topbar{background: rgba(7, 9, 12, 0.96); border-bottom: 1px solid var(--border); padding: 14px 16px; display: flex; align-items: center; justify-content: space-between; position: sticky; top: 0px; z-index: 10; backdrop-filter: blur(20px);}
#famScreen .tb-brand{font-family: var(--mono); font-size: 11px; letter-spacing: 2px; text-transform: uppercase; color: var(--teal2);}
#famScreen .tb-right{display: flex; align-items: center; gap: 10px;}
#famScreen .tb-name{font-size: 13px; color: var(--muted); font-weight: 500;}
#famScreen .tb-signout{background: none; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; font-size: 12px; color: var(--muted); cursor: pointer; padding: 6px 10px; border-radius: 6px; font-family: Inter, sans-serif; transition: color 0.15s; touch-action: manipulation; -webkit-tap-highlight-color: transparent;}
#famScreen .tb-signout:hover{color: var(--text);}
#famScreen .content{flex: 1 1 0%; padding-top: 24px; padding-right: 20px; padding-left: 20px; padding-bottom: calc(96px + env(safe-area-inset-bottom)); max-width: min(560px, -24px + 390px); margin: 0px auto; width: 100%; transition: opacity 150ms;}
#famScreen .ftab{display: none;}
#famScreen .ftab.on{display: block;}
#famScreen .status-card{background: var(--green); border-radius: 20px; padding: 28px 24px; margin-bottom: 24px; color: rgb(255, 255, 255); position: relative; overflow: hidden;}
#famScreen .status-card::after{content: ""; position: absolute; top: -30px; right: -30px; width: 120px; height: 120px; border-radius: 50%; background: rgba(255, 255, 255, 0.06);}
#famScreen .section{margin-bottom: 24px;}
#famScreen .section-title{font-size: 12px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted); margin-bottom: 12px; padding: 0px 2px; font-weight: 600;}
#famScreen .card{background: var(--bg2); border-radius: 12px; overflow: hidden; border: 1px solid var(--border);}
#famScreen .psw-card{background: var(--bg2); border-radius: 12px; padding: 20px; border: 1px solid var(--border); display: flex; align-items: center; gap: 16px; margin-bottom: 24px; transition: background 0.15s;}
#famScreen .psw-card:hover{background: var(--surface);}
#famScreen .psw-avatar{width: 56px; height: 56px; border-radius: 50%; background: var(--green-l); border: 2px solid var(--green-b); display: flex; align-items: center; justify-content: center; font-family: Inter, sans-serif; font-size: 20px; color: var(--green); font-weight: 600; flex-shrink: 0;}
#famScreen .psw-info{flex: 1 1 0%;}
#famScreen .psw-name{font-size: 16px; font-weight: 600; margin-bottom: 2px; color: var(--text);}
#famScreen .psw-title{font-size: 12px; color: var(--muted);}
#famScreen .visit-row{display: flex; align-items: center; padding: 14px 16px; border-bottom: 1px solid var(--border); gap: 12px; transition: background 0.12s; cursor: pointer;}
#famScreen .visit-row:hover{background: var(--surface);}
#famScreen .visit-date-box{width: 44px; text-align: center; flex-shrink: 0;}
#famScreen .visit-date-day{font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); font-weight: 500;}
#famScreen .visit-date-num{font-family: Inter, sans-serif; font-size: 22px; color: var(--text); line-height: 1; font-weight: 600;}
#famScreen .visit-info{flex: 1 1 0%;}
#famScreen .visit-psw{font-size: 14px; font-weight: 500; color: var(--text);}
#famScreen .visit-time{font-size: 12px; color: var(--muted); margin-top: 2px;}
#famScreen .visit-hours{font-size: 15px; font-weight: 600; color: var(--accent);}
#famScreen .msg-thread-wrap{background: var(--bg); border-radius: 16px; overflow: hidden; box-shadow: rgba(0, 0, 0, 0.06) 0px 1px 4px; border: 1px solid var(--border); margin-bottom: 24px;}
#famScreen .msg-thread-body{padding: 16px 20px; display: flex; flex-direction: column; gap: 10px; max-height: 320px; overflow-y: auto;}
#famScreen .msg-input-row{display: flex; gap: 8px; padding: 14px 20px; border-top: 1px solid var(--border); align-items: flex-end;}
#famScreen .msg-input-field{flex: 1 1 0%; background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: 10px 13px; font-size: 16px; font-family: Inter, sans-serif; color: var(--text); outline: none; resize: none; transition: border-color 0.15s;}
#famScreen .msg-input-field:focus{border-color: var(--accent);}
#famScreen .msg-send-btn{width: 44px; height: 44px; border-radius: 50%; background: var(--green); color: rgb(255, 255, 255); display: flex; align-items: center; justify-content: center; cursor: pointer; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; flex-shrink: 0; touch-action: manipulation; -webkit-tap-highlight-color: transparent; transition: background 0.15s;}
#famScreen .msg-send-btn:hover{background: var(--green-d);}
#famScreen .msg-send-btn svg{width: 18px; height: 18px;}
#famScreen .msg-char-count{font-size: 11px; color: var(--muted); text-align: right; padding: 0px 20px 8px; font-family: Inter, sans-serif;}
#famScreen .visit-detail{padding: 12px 20px 16px; border-top: 1px solid var(--border); background: var(--surface);}
